import { createChatOrchestrator } from './chatOrchestrator.js';
import type { AIProvider } from '../types/ai.js';
import { PromptBuilder } from '../infrastructure/builders/promptBuilder.js';
import type { ChatSession } from '../types/session.js';

const promptBuilder = new PromptBuilder({ identity: 'You are a test assistant.' });

const createSession = (content: string): ChatSession => ({
  sessionId: 's1',
  userId: 'u1',
  entries: [{ role: 'user', content, timestamp: new Date().toISOString() }],
});

const createRejectingProvider = (reason: any): AIProvider => ({
  async *sendMessage() {
    throw reason;
  },
  async generateStructured<T>() {
    return {} as T;
  },
});

describe('ChatOrchestrator onError non-Error rejections', () => {
  it('coerces a string rejection to an Error and calls onError', async () => {
    let receivedError: Error | undefined;
    const hooks = {
      onError: async (_session: ChatSession, error: Error) => {
        receivedError = error;
      },
    };

    const orchestrator = createChatOrchestrator(
      createRejectingProvider('string boom'),
      promptBuilder,
      undefined,
      { hooks }
    );

    try {
      await orchestrator.processMessage(createSession('hi'));
    } catch (e) {
      // Expected to throw
    }

    expect(receivedError).toBeDefined();
    expect(receivedError).toBeInstanceOf(Error);
    expect(receivedError?.message).toBe('string boom');
    expect((receivedError as any).cause).toBe('string boom');
  });

  it('coerces a plain object rejection to an Error and calls onError', async () => {
    let receivedError: Error | undefined;
    const hooks = {
      onError: async (_session: ChatSession, error: Error) => {
        receivedError = error;
      },
    };

    const reason = { code: 500, message: 'object boom' };
    const orchestrator = createChatOrchestrator(
      createRejectingProvider(reason),
      promptBuilder,
      undefined,
      { hooks }
    );

    try {
      await orchestrator.processMessage(createSession('hi'));
    } catch (e) {
      // Expected to throw
    }

    expect(receivedError).toBeDefined();
    expect(receivedError).toBeInstanceOf(Error);
    expect(receivedError?.message).toContain('object boom');
    expect((receivedError as any).cause).toBe(reason);
  });
});

